onClick:
{{
  Table_aus.selectedRow.sid != null && Table_aus.selectedRow.sid !== ""
    ? update_rs_ausgabe.run()
        .then(() => insertAusgabe.run())
        .then(() => {
            monatsliste_aus.run();
            showAlert('Ausgabe aktualisiert ✅', 'success');
            removeValue("");
        })
        .catch(() => showAlert('Fehler beim Aktualisieren ❌', 'error'))
    : insertAusgabe.run()
        .then(() => {
            monatsliste_aus.run();
            showAlert('Ausgabe gespeichert ✅', 'success');
            removeValue("");
        })
        .catch(() => showAlert('Fehler beim Speichern ❌', 'error'))
}}
